using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using NexoraEmployeePayroll.Data;using NexoraEmployeePayroll.Models;
namespace NexoraEmployeePayroll.Controllers;[Authorize(Roles="Admin,HROfficer")]public class DepartmentController(ApplicationDbContext db):Controller{public async Task<IActionResult> Index()=>View(await db.Departments.Include(x=>x.Employees).ToListAsync());[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(string departmentName){if(!string.IsNullOrWhiteSpace(departmentName)){db.Departments.Add(new Department{DepartmentName=departmentName.Trim()});await db.SaveChangesAsync();}return RedirectToAction(nameof(Index));}}
